"""Markdown export: the analysis (when there is one) followed by the transcript."""

from __future__ import annotations

from ..models import UNKNOWN_SPEAKER, Segment, speaker_turns
from .transcript import fmt_time

HEADINGS = {
    "en": {"summary": "Summary", "key_points": "Key points", "chapters": "Chapters", "quotes": "Quotes",
           "actions": "Action items", "transcript": "Transcript", "made": "Generated by {provider} / {model}"},
    "cs": {"summary": "Shrnutí", "key_points": "Hlavní body", "chapters": "Kapitoly", "quotes": "Citáty",
           "actions": "Úkoly", "transcript": "Přepis", "made": "Vytvořeno: {provider} / {model}"},
}


def speaker_name(speaker: str, names: dict[str, str]) -> str:
    return names.get(speaker) or speaker


def render_transcript(segments: list[Segment], names: dict[str, str]) -> str:
    out = []
    for turn in speaker_turns(segments):
        who = "" if turn["speaker"] == UNKNOWN_SPEAKER else f" **{speaker_name(turn['speaker'], names)}**:"
        out.append(f"`{fmt_time(turn['start'])}`{who} {turn['text']}")
    return "\n\n".join(out) + "\n"


def render(title: str | None, segments: list[Segment], names: dict[str, str], analysis: dict | None = None) -> str:
    lines = [f"# {title}", ""] if title else []
    if analysis:
        h = HEADINGS.get(analysis.get("language"), HEADINGS["en"])
        lines += [f"*{h['made'].format(provider=analysis.get('provider', '?'), model=analysis.get('model', '?'))}*", ""]
        if analysis.get("summary"):
            lines += [f"## {h['summary']}", "", analysis["summary"], ""]
        if analysis.get("key_points"):
            lines += [f"## {h['key_points']}", ""] + [f"- {p}" for p in analysis["key_points"]] + [""]
        if analysis.get("chapters"):
            lines += [f"## {h['chapters']}", ""]
            for c in analysis["chapters"]:
                lines.append(f"- `{fmt_time(c['start'])}` **{c['title']}**" + (f" — {c['summary']}" if c.get("summary") else ""))
            lines.append("")
        if analysis.get("quotes"):
            lines += [f"## {h['quotes']}", ""]
            for q in analysis["quotes"]:
                lines.append(f"> {q['text']}  \n> — {speaker_name(q.get('speaker', ''), names)}, `{fmt_time(q['time'])}`")
                lines.append("")
        if analysis.get("action_items"):
            lines += [f"## {h['actions']}", ""]
            for a in analysis["action_items"]:
                owner = f"**{a['owner']}**: " if a.get("owner") else ""
                when = f" (`{fmt_time(a['time'])}`)" if a.get("time") is not None else ""
                lines.append(f"- [ ] {owner}{a['text']}{when}")
            lines.append("")
        lines += [f"## {h['transcript']}", ""]
    return "\n".join(lines) + "\n" + render_transcript(segments, names)
